def generate_synthetic_data(df_original, noise_level=0.03):
    """
    Gera um novo DataFrame adicionando ruído gaussiano aos dados originais.
    """
    df_synthetic = df_original.copy()
    colunas_medicao = [col for col in df_original.columns if col not in ['Tempo', 'RPM']]

    for col in colunas_medicao:
        std_dev = df_original[col].std()
        if std_dev == 0:
            std_dev = df_original[col].mean() * 0.01 

        ruido = np.random.normal(loc=0, scale=std_dev * noise_level, size=len(df_original))
        df_synthetic[col] = df_original[col] + ruido

    return df_synthetic

def augment_folder(folder_path, dest_folder_name, n_copies=3):
    base_dir = os.path.dirname(folder_path)
    dest_path = os.path.join(base_dir, dest_folder_name)

    if not os.path.exists(dest_path):
        os.makedirs(dest_path)

    excel_files = [f for f in os.listdir(folder_path) if f.endswith('.xlsx')]

    for file in excel_files:
        file_path = os.path.join(folder_path, file)
        try:
            df_real = pd.read_excel(file_path)
            nome_base = os.path.splitext(file)[0]

            for i in range(1, n_copies + 1):
                current_noise = np.random.uniform(0.02, 0.05) 
                df_fake = generate_synthetic_data(df_real, noise_level=current_noise)
                fake_filepath = os.path.join(dest_path, f"{nome_base}_sintetico_v{i}.xlsx")
                df_fake.to_excel(fake_filepath, index=False)
        except Exception as e:
            print(f"Erro ao processar {file}: {e}")

# Executando o Data Augmentation para todas as pastas
